def apply(func, *args, **kwargs): return func(*args, **kwargs)
def identity(x): return x
def thread_first(*funcs): return lambda x: [f(x) for f in funcs]def compose_left(*funcs): return lambda x: [f(x) for f in reversed(funcs)]
